volumeCode=c=>c.code||'文稿';
const bookById=new Map(chapters.map(c=>[c.id,c]));
const bookPartTitle=id=>bookParts.find(p=>p.id===id)?.title||'';
links=function(list){return list.map(c=>`<a class="chapter-link" href="#read/${c.id}"><span class="volume-code">${esc(c.code||'')}</span><span class="volume-title">${esc(c.code?c.title.replace(/^卷轴\s*[A-Za-z]：/,''):c.title)}<small>${esc(c.en)} · ${c.paragraphs.length?c.paragraphs.length+' 段导览材料':'待补材料'}</small></span><span class="volume-enter">${c.code?'进入卷轴':'打开篇目'} ↗</span></a>`).join('')};
function bookList(){return bookParts.map(part=>{let list=chapters.filter(c=>c.part===part.id);return `<section class="book-part" id="part-${part.id}"><div class="book-part-heading"><h2>${part.title}</h2><p>${part.en}</p></div>${part.id==='convolutes'?`<h3>大写字母卷轴 A–Z</h3>${links(list.filter(c=>/^[A-Z]$/.test(c.code)))}<h3>小写字母卷轴</h3><p class="note">手稿未使用 c、e、f、h、j、n、o、q 编号。</p>${links(list.filter(c=>/^[a-z]$/.test(c.code)))}`:links(list)}</section>`}).join('')}
library=function(term=''){return `<section class="section archive-library"><div class="library-backdrop">${plate('library')}</div><h1>全书导览</h1><p>七个部分 · 三十六个主题卷轴</p><nav class="book-jump" aria-label="全书各部分">${bookParts.map(p=>`<a href="#part-${p.id}" data-book-part="${p.id}">${p.title}</a>`).join('')}</nav><label for="search">检索人物、地点或笔记编号</label><input id="search" type="search" placeholder="游荡者 / 波德莱尔 / A1,1" value="${esc(term)}"><div id="results" class="listing">${bookList()}</div></section>`};
const bookSearchOriginal=search;
search=function(term){if(!term){document.querySelector('#results').innerHTML=bookList();bindBookJump();return}bookSearchOriginal(term)};
function bindBookJump(){document.querySelectorAll('[data-book-part]').forEach(a=>a.onclick=e=>{e.preventDefault();if(document.querySelector('#search')?.value){document.querySelector('#search').value='';search('')}document.getElementById('part-'+a.dataset.bookPart)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})})}
const bookIllustrations={A:['dream','vivienne','vero','panoramas'],B:['fashion','commerce','street'],C:['boulevard','opera','street'],D:['street','commerce'],E:['boulevard','haussmann','street'],F:['dream','panoramas'],G:['grandville','dream','commerce'],H:['library','commerce'],I:['library','fashion'],J:['baudelaire','street','boulevard'],K:['dream','library','boulevard'],L:['library','dream'],M:['street','boulevard','opera'],N:['library','benjamin'],O:['commerce','street'],P:['boulevard','street'],Q:['panoramas','dream'],R:['fashion','dream'],S:['grandville','fashion'],T:['opera','street'],U:['dream','boulevard'],V:['street','commerce'],W:['fourier','dream'],X:['library','commerce'],Y:['daguerre','boulevard'],Z:['fashion','commerce'],a:['street','boulevard'],b:['grandville','street'],d:['library','street'],g:['commerce','boulevard'],i:['commerce','library'],k:['street','boulevard'],l:['boulevard','street'],m:['street','library'],p:['library','fourier'],r:['dream','library']};
const previousChapterArt=chapterArt;
chapterArt=c=>bookIllustrations[c.code]?.[0]||previousChapterArt(c);
function insertedPictures(c){let slots=new Map(),chars=0,last=0,count=0,keys=bookIllustrations[c.code]||['library','dream'];for(let i=0;i<c.paragraphs.length-1;i++){chars+=c.paragraphs[i].length;let p=c.paragraphs[i],next=c.paragraphs[i+1];if(chars-last>=2600&&p.length>65&&!/英文原文/.test(p)&&!/中文解析|中文译/.test(next)&&count<3&&c.paragraphs.length-i>5){count++;slots.set(i,keys[count%keys.length]);last=chars}}return slots}
reader=function(id,pos){if(legacyReadingLinks[id]){let a=legacyReadingLinks[id][pos||'0']||Object.values(legacyReadingLinks[id])[0];id=a.id}let c=bookById.get(id);if(!c)return library();let idx=chapters.indexOf(c),group=chapters.filter(x=>x.part===c.part),pics=insertedPictures(c);return `<div class="reading book-reading"><aside><a href="#library" class="back-link">← 全书导览</a><p class="side-part">${bookPartTitle(c.part)}</p>${group.map(x=>`<a href="#read/${x.id}" ${x.id===id?'aria-current="page"':''}>${esc(x.title)}</a>`).join('')}</aside><article><div class="reading-scene">${plate(chapterArt(c),'chapter-painting',true)}<div class="reading-title"><p>${esc(c.code||bookPartTitle(c.part))}</p><h1>${esc(c.title)}</h1><p class="book-english">${esc(c.en)}</p></div></div><div class="reading-body"><div class="tools">${c.paragraphs.length?`<button id="mark">${localStorage.getItem('read-'+id)?'已读':'标记为已读'}</button>`:''}<a href="#notebook">阅读札记 ↗</a></div>${c.paragraphs.length?'<p class="note">已收录导览材料，非经校勘的原著全文；引文版本与页码待核对。</p>':'<div class="missing-material"><h2>材料待补</h2><p>目录位置已建立。所提供的导览尚未收录这一篇目的独立材料。</p><a href="#library" class="primary-link">返回全书导览 ↗</a></div>'}${c.sections.length?`<details class="entry-outline"><summary>本卷章节线索 · ${c.sections.length} 节</summary>${c.sections.map(s=>`<a href="#read/${id}/${s.start}" class="outline-link">${esc(s.title)}</a>`).join('')}</details>`:''}${c.paragraphs.map((p,i)=>`<p id="p${i}" class="${/^\[[A-Za-z]|英文原文/.test(p)?'fragment':''}">${esc(p)}</p>${pics.has(i)?`<div class="in-volume-art">${plate(pics.get(i))}<p class="note">${esc(c.title)} · 主题配图</p></div>`:''}`).join('')}<div class="tools book-pagination">${idx>0?`<a class="primary-link" href="#read/${chapters[idx-1].id}">← ${esc(chapters[idx-1].title)}</a>`:''}${idx<chapters.length-1?`<a class="primary-link" href="#read/${chapters[idx+1].id}">${esc(chapters[idx+1].title)} ↗</a>`:''}</div></div></article></div>`};
const bookHomeOriginal=home;
home=function(){return bookHomeOriginal().replace(links(chapters.slice(0,4)),links(chapters.filter(c=>['A','B','C','M'].includes(c.code)))).replace(`全部 ${chapters.length} 个阅读单元`,'浏览全书七个部分')};
const bookRenderOriginal=render;
render=function(){let [route,id,pos]=decodeURI(location.hash.slice(1)).split('/');if(route==='read'&&legacyReadingLinks[id]){let a=legacyReadingLinks[id][pos||'0']||Object.values(legacyReadingLinks[id])[0];history.replaceState(null,'',`#read/${a.id}/${a.pos}`)}bookRenderOriginal();if(document.querySelector('#search'))bindBookJump();if(route==='sources')document.querySelector('.section')?.insertAdjacentHTML('beforeend','<h2>目录与材料状态</h2><p>网站依照用户提供的英文版目录分为七部分，含26个大写卷轴及10个小写卷轴。目录结构与所收录材料分别标示；待补入口不表示原著缺少该部分。</p>')};
removeEventListener('hashchange',bookRenderOriginal);addEventListener('hashchange',render);render();
